export interface LinkPreview {
  href: string;
  label: string;
}

const MAX_URL_LENGTH = 2048;
const BLOCKED_SCHEMES = /^(javascript|vbscript):/i;

export function normalizeLink(raw: string): LinkPreview | null {
  if (raw.length > MAX_URL_LENGTH) {
    return null;
  }
  if (BLOCKED_SCHEMES.test(raw)) {
    return null;
  }
  const href = raw.includes(":") ? raw : `https://${raw}`;
  let label: string;
  try {
    label = new URL(href).hostname || href;
  } catch {
    label = href;
  }
  return { href, label };
}

import { normalizeLink, LinkPreview } from "./links";

export interface PostInput {
  authorId: string;
  body: string;
  links: string[];
}

export interface StoredPost {
  id: string;
  authorId: string;
  body: string;
  links: LinkPreview[];
  createdAt: string;
}

export class ValidationError extends Error {
  readonly status = 422;
}

export interface PostRepository {
  insert(post: StoredPost): Promise<void>;
}

const MAX_BODY = 5000;
const MAX_LINKS = 4;

export class PostService {
  constructor(
    private readonly repo: PostRepository,
    private readonly newId: () => string,
    private readonly now: () => Date,
  ) {}

  async create(input: PostInput): Promise<StoredPost> {
    const body = input.body.normalize("NFC").trim();
    if (body.length === 0 || body.length > MAX_BODY) {
      throw new ValidationError(`body must be 1-${MAX_BODY} characters`);
    }
    if (input.links.length > MAX_LINKS) {
      throw new ValidationError(`at most ${MAX_LINKS} links per post`);
    }

    const links: LinkPreview[] = [];
    for (const raw of input.links) {
      const link = normalizeLink(raw);
      if (!link) {
        throw new ValidationError("one of the links is not allowed");
      }
      links.push(link);
    }

    const post: StoredPost = {
      id: this.newId(),
      authorId: input.authorId,
      body,
      links,
      createdAt: this.now().toISOString(),
    };
    await this.repo.insert(post);
    return post;
  }
}

import { StoredPost } from "./postService";

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function renderPostCard(post: StoredPost): string {
  const links = post.links
    .map((l) => `<li><a href="${esc(l.href)}" rel="nofollow ugc noopener" target="_blank">${esc(l.label)}</a></li>`)
    .join("");
  return [
    `<article class="post" data-id="${esc(post.id)}">`,
    `<p>${esc(post.body)}</p>`,
    links ? `<ul class="links">${links}</ul>` : "",
    `<time datetime="${esc(post.createdAt)}"></time>`,
    `</article>`,
  ].join("");
}
